<x-layouts.admin>
    <div x-data="expensesV2()">
        <div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
            <div><div class="flex items-center gap-2 text-xs text-gray-500"><a href="{{ route('admin.dashboard') }}" class="hover:text-gray-300">Dashboard</a><span>›</span><span>Indus Gas</span><span>›</span><span class="text-gray-300">Expenses</span></div><h1 class="mt-2 text-2xl font-mono font-bold uppercase tracking-wider text-white">Expenses</h1><p class="mt-1 text-sm text-gray-500">Record every expense from one simple form.</p></div>
            <button type="button" @click="openForm()" class="rounded-lg bg-primary px-4 py-2.5 text-sm font-medium text-white hover:bg-primary-hover">+ Add expense</button>
        </div>
        <section class="mt-7 overflow-hidden rounded-xl border border-dark-700 bg-dark-800"><div class="flex items-center justify-between border-b border-dark-700 px-5 py-4"><div><h2 class="font-mono font-semibold text-white">Expense records</h2><p class="mt-1 text-xs text-gray-500">Entries added in this browser session.</p></div><span class="rounded-full bg-primary/10 px-2.5 py-1 text-xs font-medium text-primary-light" x-text="expenses.length + ' records'"></span></div><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b border-dark-700 bg-dark-900/60 text-xs uppercase tracking-wider text-gray-500"><tr><th class="px-5 py-3">Date</th><th class="px-5 py-3">Category</th><th class="px-5 py-3">Expense type</th><th class="px-5 py-3">Person</th><th class="px-5 py-3 text-right">Amount</th></tr></thead><tbody class="divide-y divide-dark-700"><template x-for="expense in expenses" :key="expense.id"><tr class="text-gray-300"><td class="px-5 py-4" x-text="expense.date"></td><td class="px-5 py-4"><span class="rounded-full bg-primary/10 px-2.5 py-1 text-xs text-primary-light" x-text="expense.category"></span></td><td class="px-5 py-4" x-text="expense.type"></td><td class="px-5 py-4" x-text="expense.person"></td><td class="px-5 py-4 text-right font-mono text-white" x-text="formatPkr(expense.amount)"></td></tr></template><tr x-show="expenses.length===0"><td colspan="5" class="px-5 py-14 text-center"><p class="font-medium text-gray-300">No expenses added yet</p><p class="mt-1 text-xs text-gray-500">Use “Add expense” to create your first entry.</p></td></tr></tbody></table></div></section>

        <div x-show="showForm" x-cloak class="fixed inset-0 z-50 overflow-y-auto bg-black/75 p-3 sm:p-6" @keydown.escape.window="showForm=false"><div class="flex min-h-full items-start justify-center py-3 sm:items-center"><form @submit.prevent="saveExpense()" class="w-full max-w-6xl rounded-2xl border border-dark-600 bg-dark-800 shadow-2xl"><div class="flex items-start justify-between border-b border-dark-700 px-6 py-4 sm:px-8"><div><p class="text-xs font-semibold uppercase tracking-wider text-primary-light">Add expense</p><h2 class="mt-1 text-xl font-mono font-semibold text-white">Expense details</h2><p class="mt-1 text-sm text-gray-500">Choose a category; only its relevant fields will appear.</p></div><button type="button" @click="showForm=false" class="text-2xl text-gray-500 hover:text-white">×</button></div><div class="space-y-5 p-6 sm:px-8 sm:py-6">
            <div><div class="flex items-center justify-between"><label class="text-sm font-medium text-gray-200">Expense category</label><button type="button" @click="openTagEditor('categories')" class="text-xs font-medium text-primary-light hover:text-white">+ Add category</button></div><p class="mt-1 text-xs text-gray-500">Choose a category to show its relevant fields.</p><div class="mt-3 flex flex-wrap gap-2"><template x-for="category in categories" :key="category.id"><div class="group relative"><button type="button" @click="chooseCategory(category.id)" :class="form.categoryId===category.id?'border-primary bg-primary/15 text-primary-light':'border-dark-600 bg-dark-900 text-gray-400'" class="rounded-lg border px-4 py-2.5 pr-14 text-sm font-medium" x-text="category.name"></button><span class="absolute inset-y-0 right-2 flex items-center gap-1"><button type="button" @click.stop="openTagEditor('categories',category)" class="p-1 text-gray-500 hover:text-white">✎</button><button type="button" @click.stop="removeTag('categories',category.id)" class="p-1 text-gray-500 hover:text-danger">×</button></span></div></template></div></div>
            <div x-show="form.category" x-cloak class="space-y-7"><div><div class="flex justify-between"><label class="text-sm font-medium text-gray-200">Expense type</label><button type="button" @click="openTagEditor('types')" class="text-xs font-medium text-primary-light hover:text-white">+ Add type</button></div><div class="mt-3 flex flex-wrap gap-2"><template x-for="type in form.category?.types||[]" :key="type.id"><div class="group relative"><button type="button" @click="form.type=type.id" :class="form.type===type.id?'border-primary bg-primary/15 text-primary-light':'border-dark-600 bg-dark-900 text-gray-400'" class="rounded-lg border px-4 py-2.5 pr-14 text-sm font-medium" x-text="type.name"></button><span class="absolute inset-y-0 right-2 flex items-center gap-1"><button type="button" @click.stop="openTagEditor('types',type)" class="p-1 text-gray-500 hover:text-white">✎</button><button type="button" @click.stop="removeTag('types',type.id)" class="p-1 text-gray-500 hover:text-danger">×</button></span></div></template></div></div>
                <div x-show="form.category?.id==='lpg'" x-cloak><label class="text-sm font-medium text-gray-200">Total number of cylinders</label><input type="number" min="1" x-model="form.cylinders" placeholder="For example: 50" class="mt-2 block w-full max-w-sm rounded-lg border border-dark-600 bg-dark-900 px-3 py-2.5 text-sm text-white outline-none focus:border-primary"></div>
                <div x-show="form.category?.fuel" x-cloak class="space-y-4"><div class="grid grid-cols-1 gap-4 sm:grid-cols-3"><div><label class="text-xs text-gray-500">Distance travelled (km)</label><input type="number" min="0" x-model="form.distance" class="mt-1.5 block w-full rounded-lg border border-dark-600 bg-dark-900 px-3 py-2.5 text-sm text-white outline-none focus:border-primary"></div><div><label class="text-xs text-gray-500">Fuel average (km/litre)</label><input type="number" min="0" step="0.01" x-model="form.average" class="mt-1.5 block w-full rounded-lg border border-dark-600 bg-dark-900 px-3 py-2.5 text-sm text-white outline-none focus:border-primary"></div><div><label class="text-xs text-gray-500">Fuel price per litre (PKR)</label><input type="number" min="0" step="0.01" x-model="form.rate" class="mt-1.5 block w-full rounded-lg border border-dark-600 bg-dark-900 px-3 py-2.5 text-sm text-white outline-none focus:border-primary"></div></div><div class="rounded-xl border border-primary/25 bg-primary/10 px-5 py-4"><div class="flex justify-between"><span class="text-sm font-medium text-primary-light">Fuel cost</span><span class="font-mono text-lg font-semibold text-white" x-text="fuelCost()===null?'Enter trip details':formatPkr(fuelCost())"></span></div><p class="mt-1 text-xs text-gray-400">(Distance ÷ average) × rate per litre</p></div></div>
                <div class="border-t border-dark-700 pt-6"><div class="flex justify-between"><label class="text-sm font-medium text-gray-200" x-text="form.category?.fuel?'Who was the driver?':'Who paid?'"></label><span class="text-xs text-gray-500" x-text="form.category?.fuel?'Choose one':'Select one or more people'"></span></div><div class="mt-3 flex flex-wrap gap-2"><template x-for="person in form.people" :key="person.id"><button type="button" @click="selectPerson(person.id)" :class="personSelected(person.id)?'border-primary bg-primary/15 text-primary-light':'border-dark-600 bg-dark-900 text-gray-400'" class="rounded-full border px-4 py-2 text-sm font-medium" x-text="person.name"></button></template></div><div x-show="!form.category?.fuel" class="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2"><template x-for="person in form.people.filter(person=>form.payers.includes(person.id))" :key="person.id"><div><label class="text-sm font-medium text-gray-200"><span x-text="person.name"></span> paid</label><div class="relative mt-2"><span class="absolute inset-y-0 left-0 flex items-center pl-3 text-sm text-gray-500">PKR</span><input type="number" min="0" x-model="form.amounts[person.id]" placeholder="0" class="block w-full rounded-lg border border-dark-600 bg-dark-900 py-2.5 pl-12 pr-3 text-sm text-white outline-none focus:border-primary"></div></div></template></div></div>
                <div class="border-t border-dark-700 pt-6"><label class="text-sm font-medium text-gray-200">Expense date</label><input type="date" x-model="form.date" class="mt-2 block w-full max-w-sm rounded-lg border border-dark-600 bg-dark-900 px-3 py-2.5 text-sm text-white outline-none focus:border-primary"></div></div><div x-show="!form.category" class="rounded-xl border border-dashed border-dark-600 bg-dark-900/40 px-5 py-8 text-center text-sm text-gray-500">Select an expense category above to see the relevant fields.</div></div><div class="flex justify-between border-t border-dark-700 px-6 py-5 sm:px-8"><p class="text-xs text-gray-500">Frontend only — records reset after refresh.</p><button type="submit" :disabled="!form.category" :class="form.category?'bg-primary text-white hover:bg-primary-hover':'cursor-not-allowed bg-dark-700 text-gray-500'" class="rounded-lg px-5 py-2.5 text-sm font-medium">Save expense</button></div></form></div></div>
        <div x-show="tagEditor.open" x-cloak class="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 p-4" @keydown.escape.window="tagEditor.open=false"><div class="w-full max-w-sm rounded-xl border border-dark-600 bg-dark-800 p-6 shadow-2xl"><h3 class="font-mono text-lg font-semibold text-white" x-text="tagEditor.id?'Edit tag':'Add new tag'"></h3><p class="mt-1 text-sm text-gray-500" x-text="tagEditor.group==='categories'?'Expense category.':'Expense type for the selected category.'"></p><input type="text" x-model="tagEditor.name" @keydown.enter.prevent="saveTag()" x-ref="tagName" placeholder="Enter a name" class="mt-5 block w-full rounded-lg border border-dark-600 bg-dark-900 px-3 py-2.5 text-sm text-white outline-none focus:border-primary"><p x-show="tagEditor.error" x-text="tagEditor.error" class="mt-2 text-xs text-danger"></p><div class="mt-6 flex justify-end gap-3"><button type="button" @click="tagEditor.open=false" class="rounded-lg px-4 py-2 text-sm text-gray-400 hover:bg-dark-700 hover:text-white">Cancel</button><button type="button" @click="saveTag()" class="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-white hover:bg-primary-hover">Save tag</button></div></div></div>
    </div>
    <script>
        window.expensesV2=()=>({showForm:false,expenses:[],form:{},tagEditor:{open:false,group:'',id:null,name:'',error:''},categories:[{id:'lpg',name:'LPG',types:[{id:'filling_charges',name:'Filling Charges'},{id:'filling_cost',name:'Filling Cost'}]},{id:'vehicle',name:'Vehicle',types:[{id:'fuel',name:'Fuel'},{id:'oil_change',name:'Oil Change'},{id:'air_pressure',name:'Air Pressure'}]},{id:'warehouse',name:'Warehouse',types:[{id:'stationery',name:'Stationery'},{id:'rent',name:'Rent'},{id:'cleaning',name:'Cleaning'},{id:'equipment',name:'Equipment'}]},{id:'bike',name:'Bike',fuel:true,people:[{id:'usman',name:'Usman'},{id:'younus',name:'Younus'},{id:'ikram',name:'Ikram'}],types:[{id:'fuel_cost',name:'Fuel Cost'}]},{id:'car',name:'Car',fuel:true,types:[{id:'fuel_cost',name:'Fuel Cost'}]},{id:'travel',name:'Travel',types:[{id:'ring_road_toll_tax',name:'Ring Road Toll Tax'},{id:'society_entry_fee',name:'Society Entry Fee'}]}],people(){return[{id:'usman',name:'Usman'},{id:'bilal',name:'Bilal'},{id:'younus',name:'Younus'},{id:'ikram',name:'Ikram'}]},openForm(){this.form={categoryId:'',category:null,type:'',people:[],payers:[],driver:'',amounts:{},cylinders:'',distance:'',average:'',rate:'',date:''};this.showForm=true},chooseCategory(id){this.form.categoryId=id;const c=this.categories.find(x=>x.id===id)||null;this.form.category=c;this.form.type=c?.types[0]?.id||'';this.form.people=(c?.people||this.people()).map(x=>({...x}));this.form.payers=[];this.form.driver='';this.form.amounts={}},selectPerson(id){this.form.category.fuel?this.form.driver=id:this.form.payers=this.form.payers.includes(id)?this.form.payers.filter(x=>x!==id):[...this.form.payers,id]},personSelected(id){return this.form.category?.fuel?this.form.driver===id:this.form.payers.includes(id)},fuelCost(){const d=Number(this.form.distance),a=Number(this.form.average),r=Number(this.form.rate);return d>0&&a>0&&r>=0?(d/a)*r:null},formatPkr(a){return `PKR ${Number(a||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2})}`},openTagEditor(group,tag=null){this.tagEditor={open:true,group,id:tag?.id||null,name:tag?.name||'',error:''};this.$nextTick(()=>this.$refs.tagName?.focus())},saveTag(){const name=this.tagEditor.name.trim(),list=this.tagEditor.group==='categories'?this.categories:this.form.category.types;if(!name){this.tagEditor.error='Please enter a name.';return}if(list.some(x=>x.name.toLowerCase()===name.toLowerCase()&&x.id!==this.tagEditor.id)){this.tagEditor.error='This tag already exists.';return}if(this.tagEditor.id)list.find(x=>x.id===this.tagEditor.id).name=name;else list.push({id:`tag-${Date.now()}`,name,types:[]});this.tagEditor.open=false},removeTag(group,id){const list=group==='categories'?this.categories:this.form.category.types,item=list.find(x=>x.id===id);if(!item||!window.confirm(`Remove “${item.name}”?`))return;if(group==='categories'){this.categories=this.categories.filter(x=>x.id!==id);if(this.form.categoryId===id)this.chooseCategory('')}else{this.form.category.types=list.filter(x=>x.id!==id);if(this.form.type===id)this.form.type=''}},saveExpense(){const c=this.form.category,t=c.types.find(x=>x.id===this.form.type)?.name||'Not selected',p=c.fuel?this.form.people.find(x=>x.id===this.form.driver)?.name||'Not selected':this.form.people.filter(x=>this.form.payers.includes(x.id)).map(x=>x.name).join(', ')||'Not selected',a=c.fuel?this.fuelCost()||0:Object.values(this.form.amounts).reduce((s,v)=>s+Number(v||0),0),d=this.form.date||'Not entered';this.expenses.unshift({id:Date.now(),category:c.name,type:t,person:p,amount:a,date:d});this.showForm=false}})
    </script>
</x-layouts.admin>
